import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const RequestLeavePage = () => {
  const navigate = useNavigate();

  // 1. NEW: State to hold the list of employees for the dropdown
  const [employees, setEmployees] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  const [formData, setFormData] = useState({
    employee_id: '', // This will hold the SELECTED employee's ID
    leave_type: 'Casual Leave',
    start_date: '',
    end_date: '',
    reason: '',
  });

  // 2. NEW: useEffect to fetch the list of employees when the page loads
  useEffect(() => {
    const fetchEmployees = async () => {
      try {
        const response = await axios.get('http://127.0.0.1:8000/api/employees/');
        setEmployees(response.data); // Store the list of employees
        setIsLoading(false);
      } catch (error) {
        console.error("Failed to fetch employees:", error);
        alert("Could not load the employee list. Please try again later.");
      }
    };
    fetchEmployees();
  }, []); // The empty [] means this runs only once

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    // Basic validation to ensure an employee is selected
    if (!formData.employee_id) {
      alert('Please select an employee.');
      return;
    }
    console.log("Submitting new leave request:", formData);
    try {
      await axios.post('http://127.0.0.1:8000/api/leave-requests/', formData);
      alert('Leave request submitted successfully!');
      navigate('/leave-tracker');
    } catch (error) {
      console.error('Error submitting leave request:', error.response.data);
      alert(`Failed to submit request: ${JSON.stringify(error.response.data)}`);
    }
  };

  return (
    <div className="flex flex-col h-full">
      <header className="bg-card-light dark:bg-card-dark p-4 border-b border-border-light"><h1 className="text-2xl font-semibold">Submit a New Leave Request</h1></header>
      <main className="flex-1 p-8">
        <div className="max-w-2xl mx-auto bg-card-light p-8 rounded-lg shadow-md">
          <form onSubmit={handleSubmit} className="space-y-6">

            {/* 3. NEW: Replaced the number input with a dropdown menu */}
            <div>
              <label htmlFor="employee_id" className="block text-sm font-medium text-subtext-light">Select Employee</label>
              <select 
                name="employee_id" 
                id="employee_id" 
                value={formData.employee_id} 
                onChange={handleChange} 
                required 
                disabled={isLoading} // Disable dropdown while loading
                className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md"
              >
                <option value="">{isLoading ? 'Loading employees...' : '-- Select an Employee --'}</option>
                {employees.map(employee => (
                  <option key={employee.id} value={employee.id}>
                    {employee.firstName} {employee.lastName} (ID: {employee.employeeId})
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label htmlFor="leave_type" className="block text-sm font-medium text-subtext-light">Leave Type</label>
              <select name="leave_type" id="leave_type" value={formData.leave_type} onChange={handleChange} className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md">
                <option>Casual Leave</option>
                <option>Sick Leave</option>
                <option>Earned Leave</option>
              </select>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label htmlFor="start_date" className="block text-sm font-medium text-subtext-light">Start Date</label>
                <input type="date" name="start_date" id="start_date" value={formData.start_date} onChange={handleChange} required className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md" />
              </div>
              <div>
                <label htmlFor="end_date" className="block text-sm font-medium text-subtext-light">End Date</label>
                <input type="date" name="end_date" id="end_date" value={formData.end_date} onChange={handleChange} required className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md" />
              </div>
            </div>

            <div>
              <label htmlFor="reason" className="block text-sm font-medium text-subtext-light">Reason for Leave</label>
              <textarea name="reason" id="reason" rows="4" value={formData.reason} onChange={handleChange} className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md" placeholder="Briefly explain the reason for your leave..."></textarea>
            </div>

            <div className="flex justify-end gap-4 border-t border-border-light pt-6">
              <button type="button" onClick={() => navigate('/leave-tracker')} className="bg-gray-200 text-gray-700 px-6 py-2 rounded-lg hover:bg-gray-300">Cancel</button>
              <button type="submit" className="bg-primary text-white px-6 py-2 rounded-lg hover:bg-blue-600">Submit Request</button>
            </div>
          </form>
        </div>
      </main>
    </div>
  );
};

export default RequestLeavePage;
